def choose_move(observation):
    def g(obj, key, default=None):
        if isinstance(obj, dict):
            return obj.get(key, default)
        return default

    def pos_from(x):
        if x is None:
            return None
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return [x[0], x[1]]
        if isinstance(x, dict):
            for a, b in (("x", "y"), ("row", "col"), ("r", "c")):
                if a in x and b in x:
                    return [x[a], x[b]]
        return None

    def find_self_pos(obs):
        for k in ("self", "agent", "player", "me"):
            v = g(obs, k)
            p = pos_from(v)
            if p is not None:
                return p
            if isinstance(v, dict):
                for kk in ("pos", "position", "loc", "location", "xy"):
                    p = pos_from(g(v, kk))
                    if p is not None:
                        return p
        for k in ("pos", "position", "loc", "location", "xy"):
            p = pos_from(g(obs, k))
            if p is not None:
                return p
        return [0, 0]

    def extract_positions(obj):
        out = []
        if obj is None:
            return out
        if isinstance(obj, dict):
            p = pos_from(obj)
            if p is not None:
                return [p]
            for k in ("items", "entities", "units", "players", "agents", "resources", "enemies", "opponents", "allies", "targets", "goals"):
                vv = g(obj, k)
                if vv is not None:
                    out.extend(extract_positions(vv))
            return out
        if isinstance(obj, (list, tuple)):
            for it in obj:
                p = pos_from(it)
                if p is not None:
                    out.append(p)
                elif isinstance(it, dict):
                    for kk in ("pos", "position", "loc", "location", "xy"):
                        p = pos_from(g(it, kk))
                        if p is not None:
                            out.append(p)
                            break
                    else:
                        out.extend(extract_positions(it))
            return out
        return out

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def clamp_step(v):
        if v > 1:
            return 1
        if v < -1:
            return -1
        return v

    me = find_self_pos(observation)

    # Collect possible target sets
    resources = []
    enemies = []
    allies = []
    neutrals = []
    for k in ("resources", "resource_positions", "food", "treasure"):
        resources.extend(extract_positions(g(observation, k)))
    for k in ("enemies", "enemy_positions", "opponents", "foes", "threats"):
