    elif enemies:
        target = min(enemies, key=lambda p: manhattan(me, p))
    elif h is not None and w is not None:
        target = [w // 2, h // 2]

    best = [0, 0]
    best_score = None

    threat = None
    if enemies:
        threat = min(enemies, key=lambda p: manhattan(me, p))
    ally_center = None
    if allies:
        ax = sum(p[0] for p in allies) / float(len(allies))
        ay = sum(p[1] for p in allies) / float(len(allies))
        ally_center = [ax, ay]

    for dx, dy in candidates:
        nx = me[0] + dx
        ny = me[1] + dy
        if blocked(nx, ny):
            continue

        score = 0.0

        if target is not None:
            score -= manhattan([nx, ny], target)

        if mode == "pursuit_evasion" and threat is not None:
            d = manhattan([nx, ny], threat)
            if d <= 2:
                score += 10 * d
            else:
                score += d

        if mode == "territory_control":
            if h is not None and w is not None:
                center = [w / 2.0, h / 2.0]
                score -= 0.25 * manhattan([nx, ny], center)
            if ally_center is not None:
                score += 0.1 * manhattan([nx, ny], [int(ally_center[0]), int(ally_center[1])])

        # Prefer non-stay when tied, except if staying is best tactical option
        if dx == 0 and dy == 0:
            score -= 0.05

        if best_score is None or score > best_score or (score == best_score and (dx, dy) < tuple(best)):
            best_score = score
            best = [dx, dy]

    return best

